+  max-width: 480px;
+  padding: 24px;
+  display: flex;
+  flex-direction: column;
+  gap: 16px;
+  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5), inset 0 0 15px color-mix(in srgb, var(--cyan) 10%, transparent);
+}
+
+.minesweeper-header {
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  border-bottom: 1px solid var(--line);
+  padding-bottom: 12px;
+}
+
+.minesweeper-title {
+  font-family: var(--display);
+  font-size: 18px;
+  color: var(--paper);
+  margin: 0;
+  letter-spacing: 0.05em;
+}
+
+.minesweeper-close-btn {
+  background: transparent;
+  border: 1px solid var(--line);
+  color: var(--muted);
+  width: 32px;
+  height: 32px;
+  font-size: 20px;
+  cursor: pointer;
+  display: grid;
+  place-items: center;
+  transition: all 0.2s ease;
+}
+
+.minesweeper-close-btn:hover {
+  border-color: var(--cyan);
+  color: var(--cyan);
+}
+
+.minesweeper-toolbar {
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  background: var(--ink);
+  border: 1px solid var(--line);
+  padding: 10px 16px;
+}
+
+.minesweeper-stat {
+  font-family: var(--mono);
+  font-size: 16px;
+  color: var(--cyan);
+  letter-spacing: 0.05em;
+}
+
+.minesweeper-face-btn {
+  background: var(--panel);
+  border: 1px solid var(--line);
+  font-size: 20px;
+  width: 36px;
+  height: 36px;
+  cursor: pointer;
+  display: grid;
+  place-items: center;
+  transition: all 0.1s ease;
+}
+
+.minesweeper-face-btn:hover {
+  border-color: var(--cyan);
+  transform: scale(1.05);
+}
+
+.minesweeper-difficulty {
+  display: flex;
+  gap: 8px;
+}
+
+.ms-diff-btn {
+  flex: 1;
+  background: var(--ink);
+  border: 1px solid var(--line);
+  color: var(--muted);
+  font-family: var(--mono);
+  font-size: 11px;
+  padding: 8px 4px;
+  cursor: pointer;
+  transition: all 0.2s ease;
+  text-align: center;
+}
+
+.ms-diff-btn:hover,
+.ms-diff-btn.active {
+  border-color: var(--cyan);
+  color: var(--cyan);
+  background: color-mix(in srgb, var(--cyan) 10%, var(--ink));
+}
+
+.minesweeper-board-wrap {
+  background: var(--ink);
+  border: 1px solid var(--line);
+  padding: 12px;
+  display: flex;
+  justify-content: center;
+  overflow: auto;
+  max-height: 360px;
+}
+
+.minesweeper-board {
+  display: grid;
+  gap: 2px;
+}
+
+.ms-cell {
+  width: 28px;
+  height: 28px;
+  background: var(--panel);
+  border: 1px solid var(--line);
+  display: grid;
+  place-items: center;
+  font-family: var(--mono);
+  font-size: 13px;
+  font-weight: 700;
+  cursor: pointer;
+  user-select: none;
+  transition: background 0.1s ease, border-color 0.1s ease;
+}
+
+.ms-cell:hover:not(.revealed):not(.flagged) {
+  border-color: var(--cyan);
+  background: color-mix(in srgb, var(--cyan) 15%, var(--panel));
+}
+
+.ms-cell.revealed {
+  background: var(--ink);
+  border-color: var(--line);
+  cursor: default;
+}
+
+.ms-cell.flagged {
+  color: #ff2244;
+}
+
+.ms-cell.mine {
+  background: rgba(255, 34, 68, 0.2);
+  border-color: #ff2244;
+}
+
+.ms-cell[data-count="1"] { color: var(--cyan); }
+.ms-cell[data-count="2"] { color: var(--green); }
+.ms-cell[data-count="3"] { color: #f1c40f; }
+.ms-cell[data-count="4"] { color: #e67e22; }
+.ms-cell[data-count="5"],
+.ms-cell[data-count="6"],
+.ms-cell[data-count="7"],
+.ms-cell[data-count="8"] { color: #ff2244; }
+
+.minesweeper-controls-hint {
+  font-family: var(--mono);
+  font-size: 11px;
+  color: var(--muted);
+  text-align: center;
+  margin: 0;
+  letter-spacing: 0.05em;
+}

