      timeEl.textContent = "⏱️ 000";
      gameOver = false;
      gameWon = false;
      firstClick = true;
      flagsCount = 0;
      faceBtn.textContent = "😊";
      minesEl.textContent = `💣 ${totalMines - flagsCount}`;

      board = [];
      for (let r = 0; r < rows; r++) {
        let row = [];
        for (let c = 0; c < cols; c++) {
          row.push({
            r, c,
            mine: false,
            revealed: false,
            flagged: false,
            count: 0
          });
        }
        board.push(row);
      }

      renderBoard();
    };
    this.msResetGame = resetGame;

    const placeMines = (safeR, safeC) => {
      let placed = 0;
      while (placed < totalMines) {
        let rr = Math.floor(Math.random() * rows);
        let cc = Math.floor(Math.random() * cols);
        if (Math.abs(rr - safeR) <= 1 && Math.abs(cc - safeC) <= 1) continue;
        if (!board[rr][cc].mine) {
          board[rr][cc].mine = true;
          placed++;
        }
      }

      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          if (board[r][c].mine) continue;
          let count = 0;
          for (let dr = -1; dr <= 1; dr++) {
            for (let dc = -1; dc <= 1; dc++) {
              let nr = r + dr;
              let nc = c + dc;
              if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && board[nr][nc].mine) {
                count++;
              }
            }
          }
          board[r][c].count = count;
        }
      }
    };

    const renderBoard = () => {
      boardEl.style.gridTemplateColumns = `repeat(${cols}, 28px)`;
      boardEl.innerHTML = "";

      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          let cellData = board[r][c];
          let cellEl = document.createElement("div");
          cellEl.className = "ms-cell";
          cellEl.dataset.r = r;
          cellEl.dataset.c = c;

          if (cellData.revealed) {
            cellEl.classList.add("revealed");
            if (cellData.mine) {
              cellEl.classList.add("mine");
              cellEl.textContent = "💣";
            } else if (cellData.count > 0) {
              cellEl.textContent = cellData.count;
              cellEl.dataset.count = cellData.count;
            }
          } else if (cellData.flagged) {
            cellEl.classList.add("flagged");
            cellEl.textContent = "🚩";
          }

          cellEl.addEventListener("click", () => {
            if (gameOver || gameWon || cellData.flagged || cellData.revealed) return;
            if (firstClick) {
              firstClick = false;
              placeMines(r, c);
              startTimer();
            }
            revealCell(r, c);
          });

          cellEl.addEventListener("contextmenu", (e) => {
            e.preventDefault();
            if (gameOver || gameWon || cellData.revealed) return;
            cellData.flagged = !cellData.flagged;
            flagsCount += cellData.flagged ? 1 : -1;
            minesEl.textContent = `💣 ${totalMines - flagsCount}`;
            renderBoard();
          });

          boardEl.appendChild(cellEl);
        }
      }
    };

    const revealCell = (r, c) => {
      let cell = board[r][c];
      if (cell.revealed || cell.flagged) return;

      cell.revealed = true;

      if (cell.mine) {
        gameOver = true;
        stopTimer();
        faceBtn.textContent = "💀";
        revealAllMines();
        renderBoard();
        return;
      }

      if (cell.count === 0) {
        for (let dr = -1; dr <= 1; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            let nr = r + dr;
            let nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
              if (!board[nr][nc].revealed && !board[nr][nc].flagged) {
                revealCell(nr, nc);
              }
            }
          }
        }
      }

      checkWin();
      renderBoard();
    };

    const revealAllMines = () => {
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          if (board[r][c].mine) {
            board[r][c].revealed = true;
          }
        }
      }
    };

    const checkWin = () => {
      let won = true;
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          if (!board[r][c].mine && !board[r][c].revealed) {
            won = false;
            break;
          }
        }
        if (!won) break;
      }

      if (won) {
        gameWon = true;
        stopTimer();
        faceBtn.textContent = "😎";
      }
    };

    faceBtn.addEventListener("click", () => {
      resetGame();
    });

    diffBtns.forEach(btn => {
      btn.addEventListener("click", () => {
        configDiff(btn.dataset.diff);
      });
    });

    resetGame();
  }
});

