    const timeEl = overlay.querySelector("#ms-time");
    const faceBtn = overlay.querySelector("#ms-face");
    const diffBtns = overlay.querySelectorAll(".ms-diff-btn");

    let currentDiff = "easy";
    let rows = 9;
    let cols = 9;
    let totalMines = 10;

