    let gameOver = false;
    let gameWon = false;
    let firstClick = true;
    let timerId = null;
    let seconds = 0;
    let flagsCount = 0;

    const configDiff = (diff) => {
      currentDiff = diff;
      if (diff === "easy") {
        rows = 9; cols = 9; totalMines = 10;
