        rows = 12; cols = 12; totalMines = 25;
      } else if (diff === "hard") {
        rows = 16; cols = 16; totalMines = 40;
      }
      diffBtns.forEach(btn => {
        btn.classList.toggle("active", btn.dataset.diff === diff);
      });
      resetGame();
    };

