          </div>
          <div class="minesweeper-board-wrap">
            <div class="minesweeper-board" id="ms-board"></div>
          </div>
          <p class="minesweeper-controls-hint">LEFT CLICK: REVEAL // RIGHT CLICK: FLAG</p>
