  },

  initMinesweeperEngine(overlay) {
    const boardEl = overlay.querySelector("#ms-board");
    const minesEl = overlay.querySelector("#ms-mines");
    const timeEl = overlay.querySelector("#ms-time");
    const faceBtn = overlay.querySelector("#ms-face");
    const diffBtns = overlay.querySelectorAll(".ms-diff-btn");

    let currentDiff = "easy";
    let rows = 9;
    let cols = 9;
    let totalMines = 10;

    let board = [];
    let gameOver = false;
    let gameWon = false;
    let firstClick = true;
    let timerId = null;
    let seconds = 0;
    let flagsCount = 0;

    const configDiff = (diff) => {
      currentDiff = diff;
      if (diff === "easy") {
        rows = 9; cols = 9; totalMines = 10;
      } else if (diff === "medium") {
        rows = 12; cols = 12; totalMines = 25;
      } else if (diff === "hard") {
        rows = 16; cols = 16; totalMines = 40;
      }
