    const startTimer = () => {
      if (timerId) return;
      timerId = setInterval(() => {
        seconds++;
        if (seconds > 999) seconds = 999;
        timeEl.textContent = `⏱️ ${String(seconds).padStart(3, '0')}`;
      }, 1000);
    };

    const resetGame = () => {
      stopTimer();
      seconds = 0;
      timeEl.textContent = "⏱️ 000";
      gameOver = false;
      gameWon = false;
      firstClick = true;
      flagsCount = 0;
      faceBtn.textContent = "😊";
      minesEl.textContent = `💣 ${totalMines - flagsCount}`;

      board = [];
      for (let r = 0; r < rows; r++) {
        let row = [];
        for (let c = 0; c < cols; c++) {
          row.push({
            r, c,
            mine: false,
            revealed: false,
            flagged: false,
            count: 0
          });
        }
        board.push(row);
      }

      renderBoard();
    };
    this.msResetGame = resetGame;

    const placeMines = (safeR, safeC) => {
      let placed = 0;
      while (placed < totalMines) {
        let rr = Math.floor(Math.random() * rows);
        let cc = Math.floor(Math.random() * cols);
        if (Math.abs(rr - safeR) <= 1 && Math.abs(cc - safeC) <= 1) continue;
        if (!board[rr][cc].mine) {
          board[rr][cc].mine = true;
          placed++;
        }
      }

      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          if (board[r][c].mine) continue;
          let count = 0;
          for (let dr = -1; dr <= 1; dr++) {
            for (let dc = -1; dc <= 1; dc++) {
              let nr = r + dr;
              let nc = c + dc;
              if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && board[nr][nc].mine) {
                count++;
              }
            }
          }
          board[r][c].count = count;
        }
      }
    };

