$cssContent = @'
/* Cyber Minesweeper Arcade App Icon & Modal Styles */
.minesweeper-app-icon-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  background: transparent;
  border: none;
  padding: 12px;
  cursor: pointer;
  transition: all 0.2s ease;
  text-align: center;
  pointer-events: auto;
  width: 100%;
}

.minesweeper-app-icon-card:hover {
  border: none;
  transform: translateY(-3px);
  box-shadow: none;
}

.minesweeper-app-icon {
  width: 72px;
  height: 72px;
  background: var(--ink);
  border: 1px solid var(--cyan);
  display: grid;
  place-items: center;
  box-shadow: inset 0 0 10px color-mix(in srgb, var(--cyan) 15%, transparent);
  position: relative;
  pointer-events: none;
}

.minesweeper-icon-canvas {
  width: 56px;
  height: 56px;
  display: block;
  pointer-events: none;
}

.minesweeper-icon-label {
  font-family: var(--display);
  font-size: 16px;
  color: var(--paper);
  margin: 0;
  pointer-events: none;
}

/* Modal Overlay */
.minesweeper-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(9, 11, 10, 0.85);
  backdrop-filter: blur(4px);
  z-index: 1000;
  display: grid;
  place-items: center;
  padding: 12px;
  animation: msFadeIn 0.2s ease forwards;
}

@keyframes msFadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.minesweeper-modal-container {
  background: var(--panel);
  border: 1px solid var(--cyan);
  width: 100%;
  max-width: 480px;
  max-height: 96vh;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5), inset 0 0 15px color-mix(in srgb, var(--cyan) 10%, transparent);
  box-sizing: border-box;
}

.minesweeper-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--line);
  padding-bottom: 6px;
}

.minesweeper-title {
  font-family: var(--display);
  font-size: 15px;
  color: var(--paper);
  margin: 0;
  letter-spacing: 0.05em;
}

.minesweeper-close-btn {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--muted);
  width: 26px;
  height: 26px;
  font-size: 16px;
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: all 0.2s ease;
}

.minesweeper-close-btn:hover {
  border-color: var(--cyan);
  color: var(--cyan);
}

.minesweeper-toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--ink);
  border: 1px solid var(--line);
  padding: 6px 12px;
}

.minesweeper-stat {
  font-family: var(--mono);
  font-size: 14px;
  color: var(--cyan);
  letter-spacing: 0.05em;
}

.minesweeper-face-btn {
  background: var(--panel);
  border: 1px solid var(--line);
  font-size: 16px;
  width: 30px;
  height: 30px;
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: all 0.1s ease;
}

.minesweeper-face-btn:hover {
  border-color: var(--cyan);
  transform: scale(1.05);
}

.minesweeper-settings {
  display: flex;
  flex-direction: column;
  gap: 6px;
  background: var(--ink);
  border: 1px solid var(--line);
  padding: 8px 10px;
}

.ms-setting-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  font-family: var(--mono);
  font-size: 11px;
  color: var(--muted);
}

.ms-size-btns {
  display: flex;
  gap: 4px;
}

.ms-size-btn {
  background: var(--panel);
  border: 1px solid var(--line);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 10px;
  padding: 3px 6px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.ms-size-btn:hover,
.ms-size-btn.active {
  border-color: var(--cyan);
  color: var(--cyan);
  background: color-mix(in srgb, var(--cyan) 10%, var(--panel));
}

.ms-mode-btn {
  background: var(--panel);
