  background: color-mix(in srgb, var(--cyan) 15%, var(--ink));
  border: 1px solid var(--cyan);
  color: var(--cyan);
  font-family: var(--mono);
  font-size: 10px;
  padding: 4px;
  cursor: pointer;
  text-align: center;
