        "..........############..........",
        ".........##############.........",
        "........################........",
        ".......##################.......",
        "......####################......",
        ".....######################.....",
        ".....#####.OO.####.OO.#####.....",
        ".....#####.EE.####.EE.#####.....",
        ".....#######################....",
        ".....#######################....",
        "......#####################.....",
